// ===== SOUND ENGINE (Web Audio API — no files needed) =====
let audioCtx = null;
let soundEnabled = true;

// ===== MENU MUSIC =====
let musicPlaying = false;
let musicGainNode = null;
let musicScheduler = null;
let musicStartTime = 0;
let musicBeat = 0;

function getAudioCtx() {
  if(!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if(audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}

function toggleSound() {
  soundEnabled = !soundEnabled;
  document.getElementById('sound-btn').textContent = soundEnabled ? '🔊' : '🔇';
  document.getElementById('sound-btn').classList.toggle('muted', !soundEnabled);
  if(!soundEnabled) {
    stopMenuMusic();
  } else {
    // Only restart music if currently on home screen
    if(document.getElementById('home').classList.contains('active')) {
      musicStarted = true;
      startMenuMusic();
    }
  }
}

// --- Low-level tone builder ---
function playTone(freq, type='sine', duration=0.12, vol=0.18, decay=0.08, startAt=null) {
  if(!soundEnabled) return;
  try {
    const ctx = getAudioCtx();
    const t = startAt !== null ? startAt : ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(musicGainNode || ctx.destination);
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(freq * 0.7, t + duration);
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + duration + decay);
    osc.start(t);
    osc.stop(t + duration + decay + 0.01);
  } catch(e) {}
}

function playChord(freqs, type='sine', duration=0.15, vol=0.12) {
  freqs.forEach((f,i) => setTimeout(()=>playTone(f, type, duration, vol), i*30));
}

// Named sound events
