// ---- MENU MUSIC ENGINE ----
// Warm tropical/bubbly melody in C major, 96 BPM
// Structure: bass ostinato + pad chords + marimba melody, loops every 8 bars

const MUSIC_BPM = 96;
const MUSIC_BEAT_DUR = 60 / MUSIC_BPM;        // seconds per beat
const MUSIC_BAR = MUSIC_BEAT_DUR * 4;         // 4/4 time
const MUSIC_LOOP = MUSIC_BAR * 8;             // 8 bars total

// Marimba-like note: short sine with fast decay, slight pitch drop
function mNote(ctx, dest, freq, t, dur=0.22, vol=0.13) {
  const osc = ctx.createOscillator();
  const g   = ctx.createGain();
  // slight detuning for warmth
  const osc2 = ctx.createOscillator();
  const g2   = ctx.createGain();
  osc.type  = 'sine'; osc2.type = 'sine';
  osc.frequency.setValueAtTime(freq, t);
  osc.frequency.exponentialRampToValueAtTime(freq * 0.94, t + dur);
  osc2.frequency.setValueAtTime(freq * 2.01, t); // subtle harmonic
  osc2.frequency.exponentialRampToValueAtTime(freq * 2.01 * 0.96, t + dur * 0.5);
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur + 0.06);
  g2.gain.setValueAtTime(vol * 0.3, t);
  g2.gain.exponentialRampToValueAtTime(0.001, t + dur * 0.5);
  osc.connect(g); g.connect(dest);
  osc2.connect(g2); g2.connect(dest);
  osc.start(t);  osc.stop(t + dur + 0.08);
  osc2.start(t); osc2.stop(t + dur * 0.6);
}

// Soft bass pulse
function bNote(ctx, dest, freq, t, dur=0.35, vol=0.09) {
  const osc = ctx.createOscillator();
  const g   = ctx.createGain();
  osc.type  = 'triangle';
  osc.frequency.setValueAtTime(freq, t);
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  osc.connect(g); g.connect(dest);
  osc.start(t); osc.stop(t + dur + 0.02);
}

// Soft pad chord
function padChord(ctx, dest, freqs, t, dur=MUSIC_BAR*2, vol=0.025) {
  freqs.forEach(freq => {
    const osc = ctx.createOscillator();
    const g   = ctx.createGain();
    osc.type  = 'sine';
    osc.frequency.setValueAtTime(freq, t);
    g.gain.setValueAtTime(0.001, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.4);
    g.gain.setValueAtTime(vol, t + dur - 0.5);
    g.gain.linearRampToValueAtTime(0.001, t + dur);
    osc.connect(g); g.connect(dest);
    osc.start(t); osc.stop(t + dur + 0.05);
  });
}

// Notes: C4=261.6, D=293.7, E=329.6, F=349.2, G=392, A=440, B=493.9, C5=523.3
const N = {
  C3:130.8, G3:196, C4:261.6, D4:293.7, E4:329.6, F4:349.2, G4:392,
  A4:440,   B4:493.9, C5:523.3, D5:587.3, E5:659.3, F5:698.5, G5:784,
  A5:880
};

// Melody pattern (beat offset, note, duration in beats)
const MELODY = [
  // Bar 1-2: playful opening
  [0,    N.E5, 0.5], [0.5,  N.G5, 0.5], [1,    N.A5, 0.75],[1.75, N.G5, 0.5],
  [2.5,  N.E5, 0.5], [3,    N.D5, 0.75],[3.75, N.C5, 0.5],
  [4,    N.D5, 0.5], [4.5,  N.E5, 0.5], [5,    N.G5, 1.0], [6,    N.E5, 0.5],
  [6.5,  N.D5, 0.5], [7,    N.C5, 1.0],
  // Bar 3-4: answer phrase
  [8,    N.G4, 0.5], [8.5,  N.A4, 0.5], [9,    N.C5, 0.75],[9.75, N.D5, 0.5],
  [10.5, N.E5, 0.5], [11,   N.D5, 0.75],[11.75,N.C5, 0.25],
  [12,   N.E5, 0.5], [12.5, N.G5, 0.5], [13,   N.A5, 1.0], [14,   N.G5, 0.5],
  [14.5, N.E5, 0.5], [15,   N.D5, 1.0],
  // Bar 5-6: rising wave
  [16,   N.C5, 0.5], [16.5, N.D5, 0.5], [17,   N.E5, 0.5], [17.5, N.G5, 0.5],
  [18,   N.A5, 1.0], [19,   N.G5, 0.5], [19.5, N.E5, 0.5],
  [20,   N.D5, 0.5], [20.5, N.C5, 0.5], [21,   N.D5, 0.75],[21.75,N.E5, 0.25],
  [22,   N.G5, 1.0], [23,   N.E5, 1.0],
  // Bar 7-8: warm resolution
  [24,   N.A4, 0.5], [24.5, N.C5, 0.5], [25,   N.E5, 0.75],[25.75,N.D5, 0.5],
  [26.5, N.C5, 0.5], [27,   N.G4, 1.0],
  [28,   N.C5, 0.5], [28.5, N.E5, 0.5], [29,   N.G5, 0.5], [29.5, N.E5, 0.5],
  [30,   N.D5, 0.5], [30.5, N.C5, 0.5], [31,   N.G4, 1.0],
];

// Bass pattern (repeating every 2 bars)
const BASS_PATTERN = [
  [0, N.C3], [1, N.G3], [2, N.C3], [3, N.G3],
  [4, N.F4/2], [5, N.C3], [6, N.F4/2], [7, N.C3], // F2 ~ 87Hz
];

// Pad chord progression (2 bars each)
const PAD_CHORDS = [
  [N.C4, N.E4, N.G4, N.C5],       // C maj
  [N.F4, N.A4, N.C5, N.F5/1],     // F maj — use actual F5
  [N.G4, N.B4, N.D5, N.G5/1],     // G maj
  [N.A4, N.C5, N.E5],              // A min
];

function scheduleLoop(loopStart) {
  if(!musicPlaying || !soundEnabled) return;
  try {
    const ctx = getAudioCtx();
    const dest = musicGainNode;

    // Pad chords — 2 bars each across 8 bars
    PAD_CHORDS.forEach((chord, i) => {
      padChord(ctx, dest, chord, loopStart + i * MUSIC_BAR * 2, MUSIC_BAR * 2, 0.028);
    });

    // Bass ostinato — repeats every 2 bars × 4
    for(let rep = 0; rep < 4; rep++) {
      const barT = loopStart + rep * MUSIC_BAR * 2;
      BASS_PATTERN.forEach(([beat, freq]) => {
        bNote(ctx, dest, freq, barT + beat * MUSIC_BEAT_DUR, 0.3, 0.08);
      });
    }

    // Melody
    MELODY.forEach(([beat, freq, dur]) => {
      mNote(ctx, dest, freq, loopStart + beat * MUSIC_BEAT_DUR, dur * MUSIC_BEAT_DUR, 0.11);
    });

    // Light hi-hat shimmer (every half beat)
    for(let b = 0; b < 32; b++) {
      const t = loopStart + b * MUSIC_BEAT_DUR * 0.5;
      const hiOsc = ctx.createOscillator();
      const hiG = ctx.createGain();
      hiOsc.type = 'square';
      hiOsc.frequency.setValueAtTime(8000 + Math.random() * 2000, t);
      hiG.gain.setValueAtTime(b % 2 === 0 ? 0.012 : 0.005, t);
      hiG.gain.exponentialRampToValueAtTime(0.001, t + 0.04);
      hiOsc.connect(hiG); hiG.connect(dest);
      hiOsc.start(t); hiOsc.stop(t + 0.05);
    }

    // Schedule next loop slightly before this one ends
    const nextLoop = loopStart + MUSIC_LOOP;
    const now = ctx.currentTime;
    const delay = (nextLoop - now - 0.5) * 1000; // 500ms before loop end
    musicScheduler = setTimeout(() => scheduleLoop(nextLoop), Math.max(0, delay));
  } catch(e) {}
}

function startMenuMusic() {
  if(musicPlaying || !soundEnabled) return;
  try {
    const ctx = getAudioCtx();
    musicPlaying = true;
    // Master gain for music (separate from SFX)
    musicGainNode = ctx.createGain();
    musicGainNode.gain.setValueAtTime(0, ctx.currentTime);
    musicGainNode.gain.linearRampToValueAtTime(0.75, ctx.currentTime + 2.0); // fade in
    musicGainNode.connect(ctx.destination);
    musicStartTime = ctx.currentTime + 0.1;
    scheduleLoop(musicStartTime);
  } catch(e) {}
}

function stopMenuMusic() {
  musicPlaying = false;
  if(musicScheduler) { clearTimeout(musicScheduler); musicScheduler = null; }
  if(musicGainNode) {
    try {
      const ctx = getAudioCtx();
      musicGainNode.gain.setValueAtTime(musicGainNode.gain.value, ctx.currentTime);
      musicGainNode.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.8);
      // disconnect after fade
      setTimeout(() => {
        try { musicGainNode.disconnect(); } catch(e) {}
        musicGainNode = null;
      }, 1000);
    } catch(e) { musicGainNode = null; }
  }
}

// Start music on first user interaction (browser autoplay policy)
let musicStarted = false;
function tryStartMusic() {
  if(!musicStarted && soundEnabled) {
    musicStarted = true;
    startMenuMusic();
  }
  document.removeEventListener('click', tryStartMusic);
  document.removeEventListener('touchstart', tryStartMusic);
}
document.addEventListener('click', tryStartMusic);
document.addEventListener('touchstart', tryStartMusic);


// ===== BACKGROUND CANVAS =====
(function() {
  const c = document.getElementById('bg-canvas');
  const ctx = c.getContext('2d');
  let W, H, bubbles = [];

  function resize() {
    W = c.width = window.innerWidth;
    H = c.height = window.innerHeight;
  }
  resize();
  window.addEventListener('resize', resize);

  for(let i = 0; i < 28; i++) {
    bubbles.push({
      x: Math.random()*1000,
      y: Math.random()*800,
      r: 4 + Math.random()*18,
      vx: (Math.random()-.5)*.3,
      vy: -.1 - Math.random()*.4,
      alpha: 0.04 + Math.random()*0.1,
      color: FLAVORS[Math.floor(Math.random()*6)].color
    });
  }

  function draw(ts) {
    ctx.clearRect(0,0,W,H);
    // Deep ocean gradient bg
    const gr = ctx.createLinearGradient(0,0,W,H);
    gr.addColorStop(0,'#0a1438');
    gr.addColorStop(0.4,'#0d1b4b');
    gr.addColorStop(0.7,'#122366');
    gr.addColorStop(1,'#091030');
    ctx.fillStyle = gr;
    ctx.fillRect(0,0,W,H);

    // Subtle radial glow center
    const cg = ctx.createRadialGradient(W*.5,H*.3,0,W*.5,H*.3,W*.7);
    cg.addColorStop(0,'rgba(39,86,208,0.12)');
    cg.addColorStop(1,'transparent');
    ctx.fillStyle = cg;
    ctx.fillRect(0,0,W,H);

    // Floating bubbles
    bubbles.forEach(b => {
      b.x += b.vx + Math.sin(ts*.0005 + b.r)*.15;
      b.y += b.vy;
      if(b.y < -30) { b.y = H + 20; b.x = Math.random()*W; }
      ctx.save();
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI*2);
      ctx.strokeStyle = b.color;
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = b.alpha;
      ctx.stroke();
      ctx.globalAlpha = b.alpha * .3;
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.restore();
    });

    // Sparkle stars
    ctx.save();
    ctx.globalAlpha = 0.3 + Math.sin(ts*.001)*.1;
    for(let i=0;i<6;i++){
      const sx = (W*.1+i*W*.15 + Math.sin(ts*.0003+i)*(W*.04));
      const sy = (H*.1 + i*H*.08 + Math.cos(ts*.0004+i)*(H*.03));
      ctx.fillStyle = '#f5c200';
      ctx.font = '12px serif';
      ctx.fillText('✦', sx, sy);
    }
    ctx.restore();

    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();

// ===== NAVIGATION =====
let activeTimers = [];
function clearActiveTimers() {
  activeTimers.forEach(id => { clearInterval(id); clearTimeout(id); });
  activeTimers = [];
  if(window._g1raf) { cancelAnimationFrame(window._g1raf); window._g1raf = null; }
}

function goHome() {
  SFX.click();
  clearActiveTimers();
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('home').classList.add('active');
  startMenuMusic();
}

function startGame(n) {
  SFX.click();
  stopMenuMusic();
  clearActiveTimers();
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('game'+n).classList.add('active');
  if(n===1) initGame1();
  if(n===2) initGame2();
  if(n===3) initGame3();
  if(n===4) initGame4();
}

// ===== UTILS =====
function spawnParticle(x, y, emoji) {
  const p = document.createElement('div');
  p.className = 'particle';
  p.textContent = emoji;
  p.style.left = x+'px';
  p.style.top = y+'px';
  document.body.appendChild(p);
  setTimeout(() => p.remove(), 900);
}

function showCombo(text, color='#f5c200') {
  const c = document.createElement('div');
  c.className = 'combo-flash';
  c.style.color = color;
  c.textContent = text;
  document.body.appendChild(c);
  setTimeout(() => c.remove(), 800);
}

function bumpScore(id, val) {
  const el = document.getElementById(id);
  if(el) { el.textContent = val+' pts'; el.classList.remove('bump'); void el.offsetWidth; el.classList.add('bump'); }
}

function makeStars(score, max) {
  const pct = score/max;
  const stars = pct > 0.7 ? 3 : pct > 0.4 ? 2 : pct > 0.1 ? 1 : 0;
  const s = ['⭐','⭐','⭐'].map((st,i)=>`<span class="star ${i<stars?'lit':''}">${st}</span>`).join('');
  return s;
}

