(function(){ const img=new Image(); img.src='data:image/png;base64,'; BOTTLE_IMGS['strawberry']=img; })();

// ===== GAME 1: SPARKLE CATCH =====
function initGame1() {
  let score=0, lives=3, flavorIdx=0, items=[], lastItem=0, speed=2.8, active=true;
  const canvas = document.getElementById('g1canvas');
  const parent = canvas.parentElement;
  const W = Math.min(parent.clientWidth, 480);
  const H = parent.clientHeight || 400;
  canvas.width = W; canvas.height = H;
  canvas.style.height = H+'px';
  const ctx = canvas.getContext('2d');
  let bottleX = W/2;

  document.getElementById('g1over').classList.remove('show');

  function setFlavor() {
    flavorIdx = Math.floor(Math.random()*6);
    const f = FLAVORS[flavorIdx];
    document.getElementById('g1dot').style.background = f.color;
    document.getElementById('g1dot').style.boxShadow = '0 0 8px '+f.color;
    document.getElementById('g1flavorname').textContent = f.emoji+' '+f.name;
  }
  setFlavor();

  function updateHUD() {
    bumpScore('g1score', score);
    document.getElementById('g1lives').textContent = '❤️'.repeat(lives) || '💀';
  }

  function spawnItem() {
    const isBonus = Math.random() < 0.18;
    let emoji, isTarget=false, fi=-1;
    if(isBonus) {
      emoji = BONUS_ITEMS[Math.floor(Math.random()*BONUS_ITEMS.length)];
    } else {
      isTarget = Math.random() < 0.42;
      fi = isTarget ? flavorIdx : Math.floor(Math.random()*6);
      while(!isTarget && fi===flavorIdx) fi=Math.floor(Math.random()*6);
      emoji = FLAVORS[fi].emoji;
    }
    items.push({
      x: 20 + Math.random()*(W-40),
      y: -30,
      vy: speed + Math.random()*1.8,
      emoji, isTarget, isBonus,
      size: 26 + Math.random()*10,
      wobble: Math.random()*Math.PI*2,
      fi
    });
  }

  function drawBottle(x, y, fi) {
    const f = FLAVORS[fi];
    const img = BOTTLE_IMGS[f.imgKey];
    ctx.save();
    ctx.shadowColor = f.color;
    ctx.shadowBlur = 26;
    ctx.shadowOffsetY = 4;
    if(img && img.complete && img.naturalWidth > 0) {
      // The images are 16:9 landscape with the bottle centered.
      // Crop to the middle ~38% of the width to isolate the bottle.
      const iw = img.naturalWidth, ih = img.naturalHeight;
      const cropW = iw * 0.38;
      const sx = (iw - cropW) / 2; // center crop
      const sy = 0;
      const bH = 110; // display height
      const bW = bH * (cropW / ih); // preserve aspect ratio of the cropped region
      ctx.drawImage(img, sx, sy, cropW, ih, x - bW/2, y - bH, bW, bH);
    } else {
      // Fallback while image loads
      const bH = 110, bW = 38;
      ctx.fillStyle = f.color;
      ctx.beginPath();
      if(ctx.roundRect) ctx.roundRect(x - bW/2, y - bH, bW, bH, 7);
      else ctx.rect(x - bW/2, y - bH, bW, bH);
      ctx.fill();
      ctx.font = '16px serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(f.emoji, x, y - bH/2);
    }
    ctx.restore();
  }

  function loop(ts) {
    if(!active) return;
    ctx.clearRect(0,0,W,H);

    // Solid dark bg so emojis are fully opaque
    ctx.fillStyle = '#0d1b4b';
    ctx.fillRect(0,0,W,H);

    // Subtle lane guides
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for(let i=0;i<W;i+=60) {
      ctx.beginPath(); ctx.moveTo(i,0); ctx.lineTo(i,H); ctx.stroke();
    }

    if(ts-lastItem > 750-Math.min(score*0.5,350)) { spawnItem(); lastItem=ts; }

    for(let i=items.length-1;i>=0;i--) {
      const it = items[i];
      it.y += it.vy;
      it.wobble += 0.05;
      const wx = it.x + Math.sin(it.wobble)*2;
      ctx.save();
      ctx.globalAlpha = 1;
      ctx.font = it.size+'px serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = '#000'; // fallback
      ctx.fillText(it.emoji, wx, it.y);
      ctx.restore();

      const bY = H - 55;
      if(it.y > bY - 25 && it.y < bY + 20 && Math.abs(wx - bottleX) < 36) {
        items.splice(i,1);
        if(it.isBonus) {
          score += 5;
          SFX.bonus();
          showCombo('+5 ✨', '#26c6da');
        } else if(it.isTarget) {
          score += 10;
          SFX.catch();
          showCombo('+10 !', FLAVORS[flavorIdx].color);
          spawnParticle(bottleX, bY - 30, FLAVORS[flavorIdx].emoji);
          if(Math.random()<0.18) setFlavor();
        } else {
          lives--;
          SFX.miss();
          showCombo('Raté ! -❤️', '#e53935');
          if(lives<=0) {
            active=false;
            SFX.gameover();
            document.getElementById('g1final').textContent=score;
            document.getElementById('g1stars').innerHTML=makeStars(score,500);
            document.getElementById('g1over').classList.add('show');
            bestScores.g1 = Math.max(bestScores.g1||0, score);
            localStorage.setItem('delio_best', JSON.stringify(bestScores));
            return;
          }
        }
        updateHUD();
      } else if(it.y > H+20) {
        items.splice(i,1);
      }
    }

    drawBottle(bottleX, H - 5, flavorIdx);

    // Catch zone indicator
    ctx.save();
    ctx.strokeStyle = FLAVORS[flavorIdx].color;
    ctx.globalAlpha = 0.2 + Math.sin(ts*.003)*.1;
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4,6]);
    ctx.beginPath();
    ctx.arc(bottleX, H - 55, 42, 0, Math.PI*2);
    ctx.stroke();
    ctx.restore();

    window._g1raf = requestAnimationFrame(loop);
  }

  canvas.addEventListener('mousemove', e => {
    const r = canvas.getBoundingClientRect();
    bottleX = (e.clientX - r.left) * (W / r.width);
  });
  canvas.addEventListener('touchmove', e => {
    e.preventDefault();
    const r = canvas.getBoundingClientRect();
    bottleX = (e.touches[0].clientX - r.left) * (W / r.width);
  }, {passive:false});

  window._g1raf = requestAnimationFrame(loop);
}

// ===== GAME 2: MATCH-3 =====
function initGame2() {
  const COLS=7, ROWS=8;
  let score=0, moves=30, combos=0, animating=false, board=[];
  // Drag state
  let dragSrc=null, dragStartX=0, dragStartY=0, dragEl=null, isDragging=false;

  document.getElementById('g2over').classList.remove('show');

  function makeBoard() {
    board=[];
    for(let r=0;r<ROWS;r++){board.push([]);for(let c=0;c<COLS;c++)board[r].push(Math.floor(Math.random()*6));}
    // ensure no initial matches
    let safety=0;
    while(findMatches().length && safety++<200) {
      for(let r=0;r<ROWS;r++) for(let c=0;c<COLS;c++) board[r][c]=Math.floor(Math.random()*6);
    }
  }
  makeBoard();

  function updateHUD() {
    bumpScore('g2score', score);
    document.getElementById('g2pts').textContent = score;
    document.getElementById('g2moves').textContent = moves;
    document.getElementById('g2combos').textContent = combos;
  }

  function getCellEl(r,c) {
    return document.getElementById('g2board').children[r*COLS+c];
  }

  function render() {
    const el = document.getElementById('g2board');
    el.innerHTML='';
    for(let r=0;r<ROWS;r++) for(let c=0;c<COLS;c++) {
      const d=document.createElement('div');
      d.className='g2cell';
      d.dataset.r=r; d.dataset.c=c;
      if(board[r][c]===-1){ d.classList.add('empty'); }
      else {
        d.textContent=FLAVORS[board[r][c]].emoji;
        d.style.background = FLAVORS[board[r][c]].bg;
        attachDrag(d, r, c);
      }
      el.appendChild(d);
    }
    updateHUD();
  }

  function attachDrag(el, r, c) {
    const onStart = (ex, ey) => {
      if(animating) return;
      dragSrc={r,c};
      dragStartX=ex; dragStartY=ey;
      isDragging=false;
      dragEl=el;
      el.style.transition='none';
      el.style.zIndex=10;
    };
    const onMove = (ex, ey) => {
      if(!dragSrc || dragEl!==el) return;
      const dx=ex-dragStartX, dy=ey-dragStartY;
      if(!isDragging && Math.abs(dx)+Math.abs(dy)>6) isDragging=true;
      if(!isDragging) return;
      // clamp drag to ~1 cell
      const cap=38;
      const cx=Math.max(-cap,Math.min(cap,dx));
      const cy=Math.max(-cap,Math.min(cap,dy));
      el.style.transform=`translate(${cx}px,${cy}px) scale(1.15)`;
      el.style.boxShadow=`0 6px 20px rgba(0,0,0,0.4)`;
      // highlight neighbour
      const nr=r+(Math.abs(dy)>Math.abs(dx)?(dy>0?1:-1):0);
      const nc=c+(Math.abs(dx)>=Math.abs(dy)?(dx>0?1:-1):0);
      document.querySelectorAll('.g2cell').forEach(x=>x.classList.remove('drag-target'));
      if(nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&(nr!==r||nc!==c)){
        const nb=getCellEl(nr,nc);
        if(nb) nb.classList.add('drag-target');
      }
    };
    const onEnd = (ex, ey) => {
      if(!dragSrc || dragEl!==el) return;
      document.querySelectorAll('.g2cell').forEach(x=>x.classList.remove('drag-target'));
      el.style.transform='';
      el.style.boxShadow='';
      el.style.zIndex='';
      el.style.transition='';
      if(!isDragging){ dragSrc=null; dragEl=null; return; }
      const dx=ex-dragStartX, dy=ey-dragStartY;
      let dr=0,dc=0;
      if(Math.abs(dx)>=Math.abs(dy)) dc=dx>0?1:-1; else dr=dy>0?1:-1;
      const nr=r+dr, nc=c+dc;
      dragSrc=null; dragEl=null; isDragging=false;
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS) return;
      doSwap(r,c,nr,nc);
    };
    // Mouse
    el.addEventListener('mousedown', e=>{e.preventDefault();onStart(e.clientX,e.clientY);
      const mm=ev=>onMove(ev.clientX,ev.clientY);
      const mu=ev=>{onEnd(ev.clientX,ev.clientY);window.removeEventListener('mousemove',mm);window.removeEventListener('mouseup',mu);};
      window.addEventListener('mousemove',mm);
      window.addEventListener('mouseup',mu);
    });
    // Touch
    el.addEventListener('touchstart', e=>{e.preventDefault();const t=e.touches[0];onStart(t.clientX,t.clientY);},{passive:false});
    el.addEventListener('touchmove', e=>{e.preventDefault();const t=e.touches[0];onMove(t.clientX,t.clientY);},{passive:false});
    el.addEventListener('touchend', e=>{e.preventDefault();const t=e.changedTouches[0];onEnd(t.clientX,t.clientY);},{passive:false});
  }

  function doSwap(r1,c1,r2,c2) {
    if(animating) return;
    // Animate slide
    const a=getCellEl(r1,c1), b=getCellEl(r2,c2);
    if(!a||!b) return;
    const cellW=a.offsetWidth, cellH=a.offsetHeight;
    const ddx=(c2-c1)*cellW, ddy=(r2-r1)*cellH;
    a.style.transition='transform 0.22s cubic-bezier(0.4,0,0.2,1)';
    b.style.transition='transform 0.22s cubic-bezier(0.4,0,0.2,1)';
    a.style.transform=`translate(${ddx}px,${ddy}px)`;
    b.style.transform=`translate(${-ddx}px,${-ddy}px)`;
    animating=true;
    const t=setTimeout(()=>{
      [board[r1][c1],board[r2][c2]]=[board[r2][c2],board[r1][c1]];
      const matches=findMatches();
      if(matches.length){
        moves--;
        SFX.swap();
        render();
        processMatches(matches);
      } else {
        // bounce back
        SFX.noMatch();
        [board[r1][c1],board[r2][c2]]=[board[r2][c2],board[r1][c1]];
        render();
        const ba=getCellEl(r1,c1), bb=getCellEl(r2,c2);
        if(ba&&bb){
          ba.style.transition='transform 0.18s cubic-bezier(0.4,0,0.2,1)';
          bb.style.transition='transform 0.18s cubic-bezier(0.4,0,0.2,1)';
          ba.style.transform=`translate(${ddx*.25}px,${ddy*.25}px)`;
          bb.style.transform=`translate(${-ddx*.25}px,${-ddy*.25}px)`;
          setTimeout(()=>{ba.style.transform='';bb.style.transform='';animating=false;},180);
        } else { animating=false; }
      }
      if(!animating && moves<=0) endGame2();
    },230);
    activeTimers.push(t);
  }

  function findMatches(){
    const m=new Set();
    for(let r=0;r<ROWS;r++) for(let c=0;c<COLS-2;c++) if(board[r][c]!==-1&&board[r][c]===board[r][c+1]&&board[r][c]===board[r][c+2]) for(let k=0;k<3;k++) m.add(r*COLS+c+k);
    for(let c=0;c<COLS;c++) for(let r=0;r<ROWS-2;r++) if(board[r][c]!==-1&&board[r][c]===board[r+1][c]&&board[r][c]===board[r+2][c]) for(let k=0;k<3;k++) m.add((r+k)*COLS+c);
    return [...m];
  }

  function processMatches(matches) {
    const pts = matches.length * 10;
    score += pts; combos++;
    SFX.match();
    const fi = board[Math.floor(matches[0]/COLS)][matches[0]%COLS];
    if(fi>=0) showCombo('+'+pts+' !', FLAVORS[fi].color);
    matches.forEach(i=>{ board[Math.floor(i/COLS)][i%COLS]=-1; });
    render();
    const t1=setTimeout(()=>{
      gravity();
      render();
      const m2=findMatches();
      if(m2.length) {
        const t2=setTimeout(()=>processMatches(m2),320);
        activeTimers.push(t2);
      } else {
        animating=false;
        if(moves<=0) endGame2();
      }
    },320);
    activeTimers.push(t1);
  }

  function gravity(){
    for(let c=0;c<COLS;c++){
      let col=board.map(r=>r[c]).filter(v=>v!==-1);
      while(col.length<ROWS) col.unshift(Math.floor(Math.random()*6));
      for(let r=0;r<ROWS;r++) board[r][c]=col[r];
    }
  }

  function endGame2(){
    SFX.win();
    document.getElementById('g2final').textContent=score;
    document.getElementById('g2stars').innerHTML=makeStars(score,1000);
    document.getElementById('g2over').classList.add('show');
    bestScores.g2=Math.max(bestScores.g2||0,score);
    localStorage.setItem('delio_best',JSON.stringify(bestScores));
  }

  render();
}

// ===== GAME 3: WHACK =====
function initGame3() {
  let score=0, timeLeft=60, targetIdx=0, streak=0;
  let activeHoles={}, holeTimers={};
  // Pace config: starts slow, speeds up every 10s
  // spawnInterval: ms between spawns (starts at 1400, floors at 500)
  // visibleDuration: how long item stays visible (starts at 2000ms, floors at 800ms)
  let spawnInterval=1400, visibleDuration=2000;
  let spawnTimer=null;

  document.getElementById('g3over').classList.remove('show');

  function setTarget(){
    targetIdx=Math.floor(Math.random()*6);
    document.getElementById('g3emoji').textContent=FLAVORS[targetIdx].emoji;
    document.getElementById('g3name').textContent=FLAVORS[targetIdx].name;
    document.getElementById('g3name').style.color=FLAVORS[targetIdx].color;
  }
  setTarget();

  const grid=document.getElementById('g3grid');
  grid.innerHTML='';
  for(let i=0;i<9;i++){
    const d=document.createElement('div');
    d.className='g3hole';
    d.dataset.i=i;
    d.innerHTML='<span class="emoji-inner"></span>';
    d.onclick=()=>holeClick(i,d);
    grid.appendChild(d);
  }

  function showItem(){
    const avail=[];
    for(let i=0;i<9;i++) if(!activeHoles[i]) avail.push(i);
    if(!avail.length) return;
    const hole=avail[Math.floor(Math.random()*avail.length)];
    const fi=Math.floor(Math.random()*6);
    activeHoles[hole]=fi;
    const d=grid.children[hole];
    d.querySelector('.emoji-inner').textContent=FLAVORS[fi].emoji;
    d.classList.add('active');
    d.style.borderColor=FLAVORS[fi].color+'80';
    const tid=setTimeout(()=>{
      if(activeHoles[hole]!==undefined){
        d.classList.remove('active','hit-right','hit-wrong');
        d.querySelector('.emoji-inner').textContent='';
        d.style.borderColor='';
        delete activeHoles[hole];
      }
    }, visibleDuration + Math.random()*200);
    holeTimers[hole]=tid;
    activeTimers.push(tid);
  }

  function scheduleSpawn(){
    spawnTimer=setTimeout(()=>{
      showItem();
      scheduleSpawn();
    }, spawnInterval + (Math.random()-0.5)*200);
    activeTimers.push(spawnTimer);
  }
  scheduleSpawn();

  function holeClick(i,d){
    if(activeHoles[i]===undefined) return;
    const fi=activeHoles[i];
    clearTimeout(holeTimers[i]);
    d.classList.remove('active');
    d.querySelector('.emoji-inner').textContent='';
    d.style.borderColor='';
    delete activeHoles[i];
    if(fi===targetIdx){
      score+=10+streak*2;
      streak++;
      SFX.pop();
      d.classList.add('hit-right');
      showCombo(streak>2?'SÉRIE x'+streak+' !':'+'+(10+streak*2), FLAVORS[fi].color);
      if(Math.random()<0.25) setTarget();
    } else {
      streak=0;
      score=Math.max(0,score-5);
      SFX.wrong();
      d.classList.add('hit-wrong');
      showCombo('Raté ! -5', '#e53935');
    }
    document.getElementById('g3pts').textContent=score;
    document.getElementById('g3streak').textContent=streak;
    bumpScore('g3score', score);
    const t=setTimeout(()=>d.classList.remove('hit-right','hit-wrong'),400);
    activeTimers.push(t);
  }

  const tickI=setInterval(()=>{
    timeLeft--;
    document.getElementById('g3time').textContent=timeLeft;
    document.getElementById('g3bar').style.width=(timeLeft/60*100)+'%';
    if(timeLeft<=15) document.getElementById('g3bar').style.background='linear-gradient(90deg,#e53935,#ff5722)';

    // Speed up every 15 seconds elapsed → 4 steps at t=15,30,45,60s elapsed
    const elapsed=60-timeLeft;
    if(elapsed>0 && elapsed%15===0){
      spawnInterval=Math.max(500, spawnInterval-225);
      visibleDuration=Math.max(800, visibleDuration-300);
      SFX.speedup();
      showCombo('Plus vite ! 🔥', '#f59300');
    }

    if(timeLeft<=0){
      clearInterval(tickI);
      SFX.gameover();
      document.getElementById('g3final').textContent=score;
      document.getElementById('g3stars').innerHTML=makeStars(score,200);
      document.getElementById('g3over').classList.add('show');
      bestScores.g3=Math.max(bestScores.g3||0,score);
      localStorage.setItem('delio_best',JSON.stringify(bestScores));
    }
  },1000);
  activeTimers.push(tickI);
}

// ===== GAME 4: MEMORY =====
function initGame4() {
  let flipped=[], matched=0, moves=0, locked=false;
  const pairs=[...FLAVORS,...FLAVORS].sort(()=>Math.random()-.5);
  document.getElementById('g4win').classList.remove('show');
  const best = bestScores.g4 || null;
  document.getElementById('g4best').textContent = best ? best+' cp' : '—';

  const board=document.getElementById('g4board');
  board.innerHTML='';
  pairs.forEach((f,i)=>{
    const card=document.createElement('div');
    card.className='g4card';
    const fi=FLAVORS.indexOf(f);
    card.dataset.fi=fi;
    card.innerHTML=`<div class="g4inner"><div class="g4face g4front">?</div><div class="g4face g4back" style="background:${f.color}22;border-color:${f.color}88">${f.emoji}<div class="card-name">${f.name}</div></div></div>`;
    card.style.background=f.bg;
    card.onclick=()=>cardClick(card);
    // stagger entrance
    card.style.animation=`popIn 0.4s ${i*.04}s both`;
    board.appendChild(card);
  });

  function updateHUD(){
    bumpScore('g4score', Math.max(0,(matched*50)-(moves*5)));
    document.getElementById('g4matched').textContent=matched+' / 6';
    document.getElementById('g4moves').textContent=moves;
  }

  function cardClick(card){
    if(locked||card.classList.contains('flipped')||card.classList.contains('matched')) return;
    SFX.flip();
    card.classList.add('flipped');
    flipped.push(card);
    if(flipped.length===2){
      locked=true;
      moves++;
      const [a,b]=flipped;
      if(a.dataset.fi===b.dataset.fi){
        a.classList.add('matched');b.classList.add('matched');
        matched++;
        SFX.pairFound();
        showCombo('Paire ! +50', FLAVORS[parseInt(a.dataset.fi)].color);
        spawnParticle(window.innerWidth*.5, window.innerHeight*.5, FLAVORS[parseInt(a.dataset.fi)].emoji);
        flipped=[];locked=false;
        updateHUD();
        if(matched===6){
          const t=setTimeout(()=>{
            SFX.win();
            document.getElementById('g4final').textContent=moves;
            document.getElementById('g4stars').innerHTML=makeStars(moves<=10?3:moves<=16?2:1,3);
            document.getElementById('g4win').classList.add('show');
            bestScores.g4=Math.min(bestScores.g4||9999,moves);
            document.getElementById('g4best').textContent=bestScores.g4+' cp';
            localStorage.setItem('delio_best',JSON.stringify(bestScores));
          },600);
          activeTimers.push(t);
        }
      } else {
        const t=setTimeout(()=>{
          a.classList.remove('flipped');b.classList.remove('flipped');
          flipped=[];locked=false;updateHUD();
        },1100);
        activeTimers.push(t);
        updateHUD();
      }
    }
  }
  updateHUD();
}